export const catalogue=games.map(g=>({...g,group:details[g.id][0],mode:details[g.id][1],tagline:details[g.id][2],instructions:details[g.id][3],experimental:['sulia','shooting'].includes(g.id),play:true,pending:false,adaptation:details[g.id][3],refs:[...g.refs,...(g.id==='dame'?['damechain','damerules']:g.id==='ludo'?['ludorules']:['shooting','pampanaa'].includes(g.id)?['panpanaa']:[])],note:g.id==='sulia'?'Traditional Sulia rules remain unverified. This original keep-away mode is explicitly experimental.':g.id==='dame'?'Ghanaian 10×10 rules with declared promotion and draw conventions.':g.note}));
