for(const id of ['pampanaa','shooting']){const g=catalogue.find(g=>g.id===id);Object.assign(g,{name:id==='pampanaa'?'Pampanaa':'Shooting',aliases:'Pampanana, Panpanaa, Pampanaa, neighborhood shooting',mode:'Neighbourhood · last player',tagline:'HIDE. LOOK. PƐW!',experimental:false,desc:'Players hide around the neighbourhood, look for one another, and pretend-shoot with a hand or stick and a mouth-made call.',rules:['Use the houses, walls and alleys to hide and look for other players.','Point with a hand or pretend stick and make the shooting sound with your mouth.','A player called out leaves the game. The last remaining player wins.'],instructions:'Six players hide among houses and alleys. Move with WASD or the joystick; drag the scene or press Q/E to look. Face a visible rival and press Pɛw! to call them out. R changes hand/stick. Walls block shots and movement. Rivals also find and eliminate one another. One hit means out; last player wins.',note:'Your neighbourhood rules replace the previous tag-five/three-lives version. Five seconds to hide and six participants are this match’s settings. Recorded mouth-made calls are generic licensed sound, not Ghana field recordings.'});}
const street=catalogue.find(g=>g.id==='football');street.mode='Choose teams & poles';street.instructions='Choose 1–7 players per side and small or big goals before kick-off. Move with WASD or the joystick, hold Shoot for power, E passes, Q switches and Shift sprints. Without the ball, Shoot tackles. Highest score after two minutes wins.';
const priority=['football','fourcorners','penalties','onepole','laski','pampanaa','rubberband'];catalogue.sort((a,b)=>{const rank=id=>priority.includes(id)?priority.indexOf(id):priority.length;return rank(a.id)-rank(b.id);});

