Object.assign(catalogue.find(g=>g.id==='chaskele'),{instructions:'Protect the tyre from ten throws. Move left/right or tap the ground to line up; time Swing as the can reaches your stick. A can must physically land inside the tyre to count against you. After a strike, the thrower retrieves it and throws again from a new position.',adaptation:'Ten-throw defence preset with physical can flight, stick contact, tyre opening and retrieval.',note:'Tyre defence and retrieval follow remembered Ghanaian play. Ten throws and the round score are digital conventions.',refs:['curriculum','graphic','playheritage']});
